mapper.select:
SELECT 
    OI.category as CATEGORY,
    SUM(OI.price * OI.quantity) as TOTAL_SUM  FROM OrderItems OI
JOIN Orders O ON OI.order_Idx = O.order_Idx
WHERE DATE_FORMAT(O.order_Date, '%Y') = #{year}
  AND DATE_FORMAT(O.order_Date, '%m') = #{month}
GROUP BY OI.category
ORDER BY TOTAL_SUM DESC;

mapper.update:
UPDATE OrderItems
SET status = #{status}
WHERE item_Idx = #{itemIdx}

UPDATE ProductOption 
   SET stock = stock - #{quantity}
 WHERE option_Idx = #{optionIdx}  AND stock >= #{quantity}
